package com.aistock.prediction.comparisonai;
import com.aistock.common.*;import com.aistock.prediction.modelcatalog.ModelRecords.Actor;import com.aistock.prediction.comparison.ComparisonRecords;import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.core.JsonParser;import jakarta.servlet.http.HttpServletRequest;import java.util.*;import org.springframework.http.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
@RestController public final class ComparisonAiController {
 private final ComparisonAiService service;private final ObjectMapper mapper;
 public ComparisonAiController(ComparisonAiService service,ObjectMapper mapper){this.service=service;this.mapper=mapper.copy().enable(JsonParser.Feature.STRICT_DUPLICATE_DETECTION).enable(DeserializationFeature.FAIL_ON_TRAILING_TOKENS);}
 @PostMapping("/api/v1/comparison-explanations") public ResponseEntity<ApiResponse<?>> generate(Authentication auth,HttpServletRequest request){var owner=owner(auth);query(request,Set.of());ComparisonAiInput input;try{var bytes=request.getInputStream().readNBytes(513);if(bytes.length>512)throw new BusinessException("AI_REQUEST_TOO_LARGE","解释请求超过上限",HttpStatus.PAYLOAD_TOO_LARGE);var n=mapper.readTree(bytes);if(n==null||!n.isObject()||n.size()!=2||!n.has("operationId")||!n.has("comparisonId")||!n.path("operationId").isTextual()||!n.path("comparisonId").isTextual())throw invalid();input=new ComparisonAiInput(ComparisonRecords.uuid(n.path("operationId").asText()),ComparisonRecords.uuid(n.path("comparisonId").asText()));}catch(BusinessException e){throw e;}catch(Exception e){throw invalid();}var result=service.generate(owner,input);var state=result.operation().path("state").asText();var status=state.equals("RUNNING")?HttpStatus.ACCEPTED:state.equals("SUCCEEDED")&&!result.replayed()&&!result.cached()?HttpStatus.CREATED:HttpStatus.OK;return ResponseEntity.status(status).body(ok(result.operation(),request));}
 @GetMapping("/api/v1/comparison-explanations") public ApiResponse<?> view(Authentication auth,HttpServletRequest request){query(request,Set.of("comparisonId"));return ok(service.view(owner(auth),ComparisonRecords.uuid(request.getParameter("comparisonId"))),request);}
 @GetMapping("/api/v1/comparison-explanations/operations/{id}") public ApiResponse<?> operation(Authentication auth,@PathVariable String id,HttpServletRequest request){query(request,Set.of());return ok(service.operation(owner(auth),ComparisonRecords.uuid(id)),request);}
 @GetMapping("/api/v1/comparison-explanations/{id}") public ApiResponse<?> get(Authentication auth,@PathVariable String id,HttpServletRequest request){query(request,Set.of());return ok(service.get(owner(auth),ComparisonRecords.uuid(id)),request);}
 private void query(HttpServletRequest r,Set<String> allowed){if(!allowed.containsAll(r.getParameterMap().keySet())||r.getParameterMap().values().stream().anyMatch(v->v.length!=1))throw invalid();}
 private UUID owner(Authentication auth){if(auth==null||!auth.isAuthenticated()||!(auth.getPrincipal() instanceof Actor a))throw new BusinessException("AUTH_REQUIRED","请先登录",HttpStatus.UNAUTHORIZED);return a.userId();}
 private ApiResponse<?> ok(Object data,HttpServletRequest r){return ApiResponse.success(data,TraceIds.normalize(r.getHeader("X-Trace-Id")));}
 private BusinessException invalid(){return new BusinessException("AI_REQUEST_INVALID","解释请求参数不正确",HttpStatus.UNPROCESSABLE_ENTITY);}
}
